record.field:
for record in self:
    if record['amount_residual'] !=0:
      record['x_studio_total_paid'] = record['amount_total_in_currency_signed'] + record['amount_residual']
    else:
      record['x_studio_total_paid'] = 0.0

for record in self:
    if record['amount_currency'] !=0:
      record['x_studio_currency_rate'] = record['balance'] / record['amount_currency']
    else:
      record['x_studio_currency_rate'] = 1.0

for record in self:
    if record['amount_total_in_currency_signed'] !=0:
      record['x_studio_currency_rate'] = record['amount_total_signed'] / record['amount_total_in_currency_signed']
    else:
      record['x_studio_currency_rate'] = 1.0

for record in self:
  if record['x_studio_pack'] == 0:
    record['x_studio_pack'] = 1
  record['x_studio_carton'] = record['quantity_done'] / record['x_studio_pack']

for record in self:
    if record['x_studio_product_weight']:
        record['x_studio_last_purchase_price'] = record['x_last_purchase_price'] / record['x_studio_product_weight']
    else:
        record['x_studio_last_purchase_price'] = 0

acc_id = self.env.ref("account.data_account_type_current_assets").id
for record in self:
  record['x_x_studio_purchase_order_account_move_line_count'] = self.env['account.move.line'].search_count([('x_studio_lc', '=', record.id), ('account_id.account_type.id', '=', acc_id)])

acc_id = self.env.ref("account.data_account_type_payable").id
for record in self:
  record['x_total_payment'] = sum(self.env['account.move.line'].search([('x_studio_lc', '=', record.id), ('account_id.account_type.id', '=', acc_id)]).mapped("amount_currency"))
